def _make_avatar(img):
    """Gufata igice cya camera muri logo ukakoramo akamenyetso k'urukiramende."""
    w, h = img.size
    box = (int(w * 0.262), int(h * 0.341), int(w * 0.704), int(h * 0.930))
    return img.crop(box).resize((128, 128))


