def secret(name, default=None):
    """Soma agaciro muri st.secrets, cyangwa muri environment variable."""
    try:
        if name in st.secrets:
            return st.secrets[name]
    except Exception:
        pass
    return os.environ.get(name, default)


def _as_list(v):
    if v is None:
        return []
    if isinstance(v, str):
        return [x.strip() for x in v.replace("\n", ",").split(",") if x.strip()]
    try:
        return [str(x).strip() for x in v if str(x).strip()]
    except TypeError:
        return [str(v).strip()]


def _valid_key(k):
    k = (k or "").strip()
    low = k.lower()
    return bool(k) and "xxxx" not in low and not low.startswith(("put_", "your_", "paste_"))


