DEFAULT_ORDER = list(PROVIDERS.keys())

Cand = namedtuple("Cand", "provider key base_url model")


def get_keys(provider):
    P = provider.upper()
    names = [f"{P}_API_KEY", f"{P}_API_KEYS"] + PROVIDERS[provider].get("alias", [])
    keys = []
    for n in names:
        keys += _as_list(secret(n))
    seen, out = set(), []
    for k in keys:
        if _valid_key(k) and k not in seen:
            seen.add(k)
            out.append(k)
    return out


def candidates(cap):
    """cap = chat | vision | stt | tts  ->  urutonde rw'ibyo gukoresha (failover)."""
    order = [o.lower() for o in _as_list(secret("PROVIDER_ORDER"))] or DEFAULT_ORDER
    order += [p for p in DEFAULT_ORDER if p not in order]
    out = []
    for p in order:
        cfg = PROVIDERS.get(p)
        if not cfg:
            continue
        P = p.upper()
        mkey = f"{P}_MODEL" if cap == "chat" else f"{P}_{cap.upper()}_MODEL"
        model = secret(mkey, cfg.get(cap))
        base = secret(f"{P}_BASE_URL", cfg.get("base_url"))
        if not model or (p == "custom" and not base):
            continue
        keys = get_keys(p)
        random.shuffle(keys)  # kugabanya umutwaro hagati ya keys nyinshi
        out += [Cand(p, k, base, model) for k in keys]
    return out


@st.cache_resource(show_spinner=False)
def _client(key, base_url):
    from openai import OpenAI

    return OpenAI(api_key=key, base_url=base_url, timeout=60.0, max_retries=0)


@st.cache_resource(show_spinner=False)
def _bad_registry():
    return {}


def _fp(c):
    return (c.provider, c.key[-6:])


def mark_bad(c, err):
    msg = str(err).lower()
    code = getattr(err, "status_code", None)
    if code in (401, 402, 403, 429) or "quota" in msg or "credit" in msg:
        _bad_registry()[_fp(c)] = time.time() + 300  # iminota 5


def rank(cands):
    now = time.time()
    bad = _bad_registry()
    good = [c for c in cands if bad.get(_fp(c), 0) < now]
    return good + [c for c in cands if c not in good]


def note_error(kind, c, err):
    msg = f"[{kind}] {c.provider if c else '-'}: {str(err)[:300]}"
    log.warning(msg)
    if DEBUG:
        st.session_state.setdefault("debug", []).append(msg)


