def new_convo():
    cid = uuid.uuid4().hex[:8]
    st.session_state.convos[cid] = {
        "title": "Ikiganiro gishya",
        "messages": [],
        "created": datetime.datetime.now().strftime("%Y-%m-%d %H:%M"),
        "titled": False,
    }
    st.session_state.current = cid
    return cid


def init_state():
    defaults = {
        "theme": THEMES[0],
        "language": list(LANGS)[0],
        "username": "",
        "avatar": AVATARS[0],
        "plugins": {k: False for k in PLUGINS},
        "custom_plugins": {},
        "usage": [],
        "convos": {},
        "current": None,
        "att_key": 0,
        "nav": NAV["chat"],
        "debug": [],
    }
    for k, v in defaults.items():
        st.session_state.setdefault(k, v)
    if st.session_state.current not in st.session_state.convos:
        new_convo()


init_state()


def cur():
    return st.session_state.convos[st.session_state.current]


def log_usage(kind):
    st.session_state.usage.append({"kind": kind, "time": datetime.datetime.now()})


# ---- callbacks ----
def cb_new_chat():
    if cur()["messages"]:
        new_convo()
    st.session_state.nav = NAV["chat"]


def cb_open(cid):
    st.session_state.current = cid
    st.session_state.nav = NAV["chat"]


def cb_delete(cid):
    st.session_state.convos.pop(cid, None)
    if st.session_state.current == cid or st.session_state.current not in st.session_state.convos:
        new_convo()


def cb_pending(text):
    st.session_state["pending"] = text


