def system_prompt():
    ss = st.session_state
    lang = LANGS.get(ss.language)
    if lang:
        li = f"Always reply in {lang}, even if the user writes in another language."
        if lang == "Kinyarwanda":
            li += " Write natural, correct Kinyarwanda."
    else:
        li = "Reply in the same language as the user's latest message (detect it automatically)."
    extra = [p["prompt"] for k, p in PLUGINS.items() if ss.plugins.get(k)]
    extra += [v["prompt"] for k, v in ss.custom_plugins.items() if ss.plugins.get(k)]
    name = f" The user's name is {ss.username}." if ss.username.strip() else ""
    return (
        "You are The_Og AI, a smart, warm and helpful assistant. "
        f"{li} Be clear, accurate and friendly; use Markdown and a few fitting emojis when helpful.{name} "
        "If asked which model, company or technology powers you, say you are The_Og AI and that "
        "you can't share details about the underlying technology. "
        + " ".join(extra)
    ).strip()


def build_payload(history):
    history = history[-30:]
    last_img = max((i for i, m in enumerate(history) if m.get("image")), default=-1)
    msgs = [{"role": "system", "content": system_prompt()}]
    for i, m in enumerate(history):
        if m.get("error"):
            continue
        if m["role"] == "user" and m.get("image") and i == last_img:
            msgs.append({
                "role": "user",
                "content": [
                    {"type": "text", "text": m["content"] or "Sobanura iyi foto."},
                    {"type": "image_url", "image_url": {"url": m["image"]}},
                ],
            })
        else:
            txt = m["content"]
            if m.get("image"):
                txt = "[ifoto yoherejwe] " + txt
            msgs.append({"role": m["role"], "content": txt})
    return msgs, last_img != -1


def chat_stream(messages, vision=False):
    """Generator: igerageza providers/keys zose kugeza imwe ikoze (failover)."""
    cands = rank(candidates("vision" if vision else "chat"))
    if not cands:
        note_error("chat", None, "Nta key ibonetse muri secrets (cap=%s)" % ("vision" if vision else "chat"))
    for c in cands:
        got = False
        try:
            stream = _client(c.key, c.base_url).chat.completions.create(
                model=c.model, messages=messages, stream=True
            )
            for chunk in stream:
                if not chunk.choices:
                    continue
                delta = chunk.choices[0].delta.content
                if delta:
                    got = True
                    yield delta
            if got:
                st.session_state["last_ok"] = True
                return
        except Exception as e:  # noqa
            note_error("chat", c, e)
            mark_bad(c, e)
            if got:
                st.session_state["last_ok"] = True
                return
    st.session_state["last_ok"] = False
    yield FRIENDLY_ERROR


def transcribe(name, data):
    lang = STT_LANG.get(LANGS.get(st.session_state.language) or "")
    for c in rank(candidates("stt")):
        try:
            kw = {"model": c.model, "file": (name, data)}
            if lang:
                kw["language"] = lang
            r = _client(c.key, c.base_url).audio.transcriptions.create(**kw)
            return r.text
        except Exception as e:  # noqa
            note_error("stt", c, e)
            mark_bad(c, e)
    return None


def synthesize(text):
    for c in rank(candidates("tts")):
        try:
            r = _client(c.key, c.base_url).audio.speech.create(
                model=c.model, voice=secret("TTS_VOICE", "alloy"), input=text[:3500]
            )
            return r.content
        except Exception as e:  # noqa
            note_error("tts", c, e)
            mark_bad(c, e)
    return None


def browser_speak(text):
    """Iyo nta TTS ihari, ikoresha ijwi ry'igikoresho (browser) -- nta API."""
    safe = json.dumps(text[:1500]).replace("</", "<" + chr(92) + "/")
    components.html(
        f"""<button id="b" style="padding:8px 14px;border-radius:12px;border:1px solid #8884;
        background:transparent;color:inherit;cursor:pointer;font-size:14px">🔊 Soma igisubizo</button>
        <script>document.getElementById('b').onclick=()=>{{const u=new SpeechSynthesisUtterance({safe});
        speechSynthesis.cancel();speechSynthesis.speak(u);}}</script>""",
        height=50,
    )


def prepare_image(f):
    try:
        im = Image.open(io.BytesIO(f.getvalue()))
        im = ImageOps.exif_transpose(im).convert("RGB")
        im.thumbnail((1280, 1280))
        buf = io.BytesIO()
        im.save(buf, "JPEG", quality=85)
        return "data:image/jpeg;base64," + base64.b64encode(buf.getvalue()).decode()
    except Exception as e:  # noqa
        note_error("image", None, e)
        return None


def data_url_bytes(url):
    return base64.b64decode(url.split(",", 1)[1])


